import { readFileSync } from "node:fs";
import { test } from "node:test";
import assert from "node:assert/strict";

import { CssSelectorError, Page, cssToXpath } from "../dist/index.js";

/**
 * Golden files generated by Scrapling 0.5.1 / cssselect 1.6.0
 * (see spikes/css-parity/py-ref.py). Comparison is by selected nodes, not by
 * XPath strings — a different but equivalent expression is fine.
 */

const corpus = JSON.parse(
  readFileSync(new URL("./fixtures/css-corpus.json", import.meta.url), "utf8"),
);
const golden = JSON.parse(
  readFileSync(new URL("./fixtures/css-golden.json", import.meta.url), "utf8"),
);

test("css fixture covers 50 selectors x 5 documents", () => {
  assert.equal(corpus.selectors.length * corpus.documents.length, 250);
});

for (const document of corpus.documents) {
  test(`css parity: ${document.id}`, async () => {
    const page = await Page.load(document.html);
    try {
      for (const selector of corpus.selectors) {
        const expected = golden[document.id][selector];
        assert.ok(expected, `missing golden for ${selector}`);

        const actual = page.css(selector).map((node) => node.path);
        assert.deepEqual(
          actual,
          expected.paths,
          `${selector} -> ${expected.xpath}`,
        );
      }
    } finally {
      page.dispose();
    }
  });
}

test("supports ::text and ::attr() like Scrapling", async () => {
  const page = await Page.load(
    "<html><body><a href='/a'>A</a><a href='/b'>B</a></body></html>",
  );
  try {
    assert.deepEqual(
      page.css("a::text").map((node) => node.text),
      ["A", "B"],
    );
    assert.deepEqual(
      page.css("a::attr(href)").map((node) => node.text),
      ["/a", "/b"],
    );
  } finally {
    page.dispose();
  }
});

test("selector.css is scoped to its node", async () => {
  const page = await Page.load(
    "<html><body><div id='a'><p class='x'>1</p></div><div id='b'><p class='x'>2</p></div></body></html>",
  );
  try {
    const [a] = page.css("#a");
    assert.deepEqual(
      a.css("p.x").map((node) => node.text),
      ["1"],
    );
    assert.deepEqual(
      page.css("p.x").map((node) => node.text),
      ["1", "2"],
    );
  } finally {
    page.dispose();
  }
});

test("unsupported selectors fail loudly instead of diverging", () => {
  for (const selector of [
    "div:has(span)",
    ":is(a, b)",
    ":where(a)",
    "input:disabled",
    "a[href:foo]",
    "div::before",
    "",
  ]) {
    assert.throws(() => cssToXpath(selector), CssSelectorError, selector);
  }
});
